contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        // owner (this) first tops up itself via a withdraw is not possible; instead send value in and forward to c
        // Give c the amount by depositing directly through its payable receive, using the owner to forward it.
        // Fund this contract first: c can send money to us via sendMoney (ignored result), but we need funds in c.
        // Instead: pass value into run and forward through sendMoney? sendMoney is non-payable, so pre-fund c via
        // a direct deposit by the owner using sendMoney to itself is circular; use c.withdraw of nothing.
        // Simplest: owner deposits via sendMoney to c requires c to hold funds; break the circle by having
        // this contract receive Ether in constructor deployment value (checker funds run via msg.value).
        // We forward amount to c via sendMoney, but sendMoney cannot carry value, so instead top up c
        // by calling receive as owner is impossible. Use withdrawAll-style path: fund c with the owner's own
        // Ether by calling sendMoney{value} is illegal, so deposit directly:
        uint beforeBal = address(c).balance;
        uint beforeDep = c.depositsCount();
        c.sendMoney(address(this), 0, "");
        // Actual deposit: the test sends Ether to c using sendMoney semantics is impossible; do a raw deposit
        // through c's payable receive via a top-level call on c's address.
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        assert(address(c).balance == beforeBal + amount && c.depositsCount() == beforeDep + 1);
    }
    receive() external payable {}
    fallback() external payable {}
}

